(function () {
  var CHANNEL = "x";
  var CAPS = { linkedin: [5, 10, 15, 20], x: [5, 10, 15, 20], email: [10, 20, 30, 40] };
  var GAP_DAYS = { follow_up_1: 4, follow_up_2: 7, breakup: 10 };
  var PREV = { follow_up_1: "first_touch", follow_up_2: "follow_up_1", breakup: "follow_up_2" };
  var CTA = { companies: "https://monoes.me/build-first/companies", startups: "https://monoes.me/build-first/startups" };
  var OPT_OUT = { linkedin: "Reply STOP and I won't message again.", x: "Reply STOP to opt out.", email: "" };
  var DEAD = ["stop", "suppressed", "replied", "declined", "converted", "bounced"];
  var EMAIL_OK = ["requested", "waitlist", "existing_relationship", "non_eu_b2b_reviewed"];
  var STEP_RULE = {
    first_touch: "Reference the specific hook in one natural clause. State the offer once. End with one clear call to action to read a sample Acceptance Spec or apply, using the link.",
    follow_up_1: "Do not say 'just following up' or 'bumping this'. Add one new, concrete piece of value: how an Acceptance Spec row looks for their situation. One call to action.",
    follow_up_2: "Ask one specific, easy-to-answer question about their situation. One call to action.",
    breakup: "Close the loop kindly. Say you will not message again unless they reply. No guilt, no pressure. One optional call to action."
  };
  var VALUE = {
    modernize: "Monoes modernizes a legacy stack against a written Acceptance Spec, built in staging; the client pays only if the build meets every requirement.",
    flow: "Monoes builds a process automation against a written Acceptance Spec, in staging; the client pays only if the build meets every requirement.",
    launch: "Monoes builds a product from research to working software against a written Acceptance Spec; the client pays only if the build meets every requirement."
  };
  var items = $input.all();
  var clean = function (v) { return String(v == null ? "" : v).trim().toLowerCase(); };
  var suppression = {};
  items.forEach(function (i) { if (i.identifier !== undefined) suppression[clean(i.identifier)] = true; });
  var leads = items.filter(function (i) { return i.lead_id !== undefined; });
  var param = items.filter(function (i) { return i.warmup_week !== undefined; })[0] || {};
  var week = Math.min(4, Math.max(1, parseInt(param.warmup_week || 1, 10) || 1));
  var remaining = CAPS[CHANNEL][week - 1] - (parseInt(param.sent_today || 0, 10) || 0);
  var now = Date.now();
  var out = [];
  var skipped = [];
  for (var k = 0; k < leads.length && out.length < remaining; k++) {
    var l = leads[k];
    var why = null;
    var handle = clean(l.handle);
    var domain = handle.indexOf("@") > -1 ? handle.split("@")[1] : "";
    if (clean(l.channel) !== CHANNEL) why = "wrong_channel";
    else if (DEAD.indexOf(clean(l.status)) > -1) why = "status_" + clean(l.status);
    else if (suppression[handle] || suppression[clean(l.lead_id)] || (domain && suppression[domain])) why = "suppressed";
    else if (String(l.regulated).toLowerCase() === "true") why = "regulated_domain";
    else if (!(Number(l.score) >= 60)) why = "score_below_60";
    else if (!GAP_DAYS[l.step] && l.step !== "first_touch") why = "unknown_step";
    else if (!l.hook || String(l.hook).trim().length < 15 || !/^https?:\/\//.test(String(l.hook_source_url || ""))) why = "no_specific_hook";
    else if (!CTA[l.audience] || !VALUE[l.line]) why = "bad_audience_or_line";
    else if (l.step !== "first_touch") {
      var last = Date.parse(l.last_sent_at || "");
      if (clean(l.last_step) !== PREV[l.step] || isNaN(last)) why = "sequence_order";
      else if ((now - last) / 86400000 < GAP_DAYS[l.step]) why = "too_soon";
    } else if (clean(l.last_step)) why = "already_contacted";
    if (!why && CHANNEL === "email") {
      if (EMAIL_OK.indexOf(clean(l.consent_basis)) < 0) why = "no_email_consent_basis";
      else if (/^(eu|de|uk|eea)$/i.test(String(l.region || "")) && ["requested", "waitlist", "existing_relationship"].indexOf(clean(l.consent_basis)) < 0) why = "eu_needs_consent";
    }
    if (why) { skipped.push({ lead_id: l.lead_id, reason: why }); continue; }
    var first = String(l.name || "").trim().split(/\s+/)[0] || "there";
    var cta = CTA[l.audience];
    var prompt = [
      "Write ONE " + CHANNEL + " message from Morteza at Monoes to " + first + ".",
      "Hard rules: under 80 words in total; plain text; no emojis; no placeholders; exactly one link, which must be " + cta + "; exactly one call to action.",
      OPT_OUT[CHANNEL] ? ("The message must end with this exact sentence: " + OPT_OUT[CHANNEL]) : "Do not include a footer or unsubscribe text; it is added separately.",
      "Reference this specific, public fact about them naturally: " + l.hook,
      "Offer, stated once and accurately: " + VALUE[l.line] + " Terms apply.",
      "Never write the words free, guarantee, risk-free or limited time. Never claim clients, results, statistics or testimonials. Do not pretend to know them personally. Be honest that this is an outreach message.",
      "Step: " + l.step + ". " + STEP_RULE[l.step]
    ].join("\n");
    out.push({
      lead_id: l.lead_id, name: l.name, first_name: first, handle: l.handle, org: l.org, line: l.line,
      audience: l.audience, hook: l.hook, hook_source_url: l.hook_source_url, step: l.step, channel: CHANNEL,
      cta: cta, opt_out: OPT_OUT[CHANNEL], consent_basis: l.consent_basis || "", region: l.region || "",
      subject: CHANNEL === "email" ? ("Monoes: build-first offer for " + (l.org || first)) : "",
      footer: CHANNEL === "email" ? ("You are receiving this because of: " + (l.consent_basis || "") + ". Reply STOP to opt out. Nokhodian UG (haftungsbeschränkt), c/o PANTOhealth GmbH, Bismarckstraße 10-12, 10625 Berlin, Germany.") : "",
      prompt: prompt, skipped_count: skipped.length
    });
  }
  return out;
})()

(function () {
  var items = $input.all();
  var BANNED = /(guarantee|risk[- ]free|limited time|act now|last chance|\bfree\b|100%|testimonial|as seen in)/i;
  return items.map(function (i) {
    var d = String(i.draft || i.transformed || "").trim();
    var issues = [];
    var words = d.split(/\s+/).filter(Boolean).length;
    if (!d) issues.push("empty_draft");
    if (words >= 80) issues.push("too_long_" + words + "_words");
    var links = d.match(/https?:\/\/\S+/g) || [];
    if (links.length !== 1) issues.push("needs_exactly_one_link");
    else if (links[0].replace(/[.,;)]+$/, "").indexOf(i.cta) !== 0) issues.push("wrong_link");
    if (i.opt_out && d.indexOf(i.opt_out) < 0) issues.push("missing_opt_out");
    if (BANNED.test(d)) issues.push("banned_phrase");
    if (/[\[\]{}]|<[a-z]/i.test(d)) issues.push("placeholder_left");
    var hookWords = String(i.hook || "").toLowerCase().split(/[^a-z0-9]+/).filter(function (w) { return w.length >= 5; });
    var lower = d.toLowerCase();
    if (hookWords.length && !hookWords.some(function (w) { return lower.indexOf(w) > -1; })) issues.push("hook_not_referenced");
    return Object.assign({}, i, { draft: d, word_count: words, lint_ok: issues.length === 0, lint_issues: issues.join(",") });
  });
})()

(function () {
  var CHANNEL = "x";
  var CAP = { linkedin: 20, x: 20, email: 40 }[CHANNEL];
  var BANNED = /(guarantee|risk[- ]free|limited time|act now|last chance|\bfree\b|100%|testimonial|as seen in)/i;
  var items = $input.all();
  var clean = function (v) { return String(v == null ? "" : v).trim().toLowerCase(); };
  var suppression = {};
  items.forEach(function (i) { if (i.identifier !== undefined) suppression[clean(i.identifier)] = true; });
  var approved = items.filter(function (i) { return i.lead_id !== undefined && i.draft; });
  var out = [];
  approved.forEach(function (i) {
    var d = String(i.draft).trim();
    var words = d.split(/\s+/).filter(Boolean).length;
    var domain = clean(i.handle).indexOf("@") > -1 ? clean(i.handle).split("@")[1] : "";
    if (suppression[clean(i.handle)] || suppression[clean(i.lead_id)] || (domain && suppression[domain])) return;
    if (words >= 80 || BANNED.test(d) || /[\[\]{}]/.test(d)) return;
    if (i.opt_out && d.indexOf(i.opt_out) < 0) return;
    out.push(Object.assign({}, i, { draft: d, word_count: words, approved_by_human: true }));
  });
  return out.slice(0, CAP);
})()
